import{_ as a,o,c as t,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"15百钱买百鸡问题","description":"简单 通过率：53.19% 时间限制：1秒 空间限制：32M 描述 公元五世纪，我国古代数学家张丘建在《算经》一书中提出了“百鸡问题”：鸡翁一值钱五，鸡母一值钱三，鸡雏三值钱一。百钱买百鸡，问鸡翁、鸡母、鸡雏各几何？ 现要求你打印出所有花一百元买一百只鸡的方式。 输入描述： 输入。","frontmatter":{"title":"15百钱买百鸡问题","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"简单 通过率：53.19% 时间限制：1秒 空间限制：32M 描述 公元五世纪，我国古代数学家张丘建在《算经》一书中提出了“百鸡问题”：鸡翁一值钱五，鸡母一值钱三，鸡雏三值钱一。百钱买百鸡，问鸡翁、鸡母、鸡雏各几何？ 现要求你打印出所有花一百元买一百只鸡的方式。 输入描述： 输入。","sidebarWeight":49,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/15百钱买百鸡问题.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/15百钱买百鸡问题.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/15百钱买百鸡问题.md"}'),i={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/15百钱买百鸡问题.md"};function n(l,e,d,c,s,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<div><h1 id="_15百钱买百鸡问题" tabindex="-1">15百钱买百鸡问题 <a class="header-anchor" href="#_15百钱买百鸡问题" aria-label="Permalink to &quot;15百钱买百鸡问题&quot;">​</a></h1><blockquote><p>本节目标：理解“15百钱买百鸡问题”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 简单 通过率：53.19% 时间限制：1秒 空间限制：32M <strong>描述</strong> 公元五世纪，我国古代数学家张丘建在《算经》一书中提出了“百鸡问题”：鸡翁一值钱五，鸡母一值钱三，鸡雏三值钱一。百钱买百鸡，问鸡翁、鸡母、鸡雏各几何？ 现要求你打印出所有花一百元买一百只鸡的方式。 <strong>输入描述：</strong> 输入任何一个整数，即可运行程序。 <strong>输出描述：</strong> 输出有数行，每行三个整数，分别代表鸡翁，母鸡，鸡雏的数量 <strong>示例1</strong> 输入： 1 ==复制== 输出： 0 25 754 18 788 11 8112 4 84</p></blockquote><p>这个问题是一个典型的枚举问题，我们可以通过遍历可能的鸡翁（公鸡）数量，然后在每个鸡翁数量下遍历可能的鸡母（母鸡）数量，最后计算出鸡雏（小鸡）的数量，检查这三种鸡的数量和价格是否满足条件。</p><p>条件是：</p><ul><li>鸡翁价格5元一只，鸡母价格3元一只，鸡雏3只1元。</li><li>总共要买100只鸡。</li><li>总共要花100元钱。</li></ul><p>鸡翁数量我们设为<code>x</code>，鸡母数量设为<code>y</code>，鸡雏数量为<code>z</code>，则有以下两个条件：</p><ul><li><code>x + y + z = 100</code>（总共买100只鸡）</li><li><code>5x + 3y + z/3 = 100</code>（总共花费100元）</li></ul><p>我们可以写一个简单的循环来遍历可能的<code>x</code>和<code>y</code>的值，然后根据上面的两个条件计算出<code>z</code>的值，并检查解是否合法。</p><p>下面是Python代码示例：</p><h1 id="输入任何一个整数-即可运行程序" tabindex="-1">输入任何一个整数，即可运行程序 <a class="header-anchor" href="#输入任何一个整数-即可运行程序" aria-label="Permalink to &quot;输入任何一个整数，即可运行程序&quot;">​</a></h1><p>_ = input()</p><h1 id="遍历鸡翁的可能数量" tabindex="-1">遍历鸡翁的可能数量 <a class="header-anchor" href="#遍历鸡翁的可能数量" aria-label="Permalink to &quot;遍历鸡翁的可能数量&quot;">​</a></h1><p>for x in range(0, 101):</p><h1 id="遍历鸡母的可能数量" tabindex="-1">遍历鸡母的可能数量 <a class="header-anchor" href="#遍历鸡母的可能数量" aria-label="Permalink to &quot;遍历鸡母的可能数量&quot;">​</a></h1><p>for y in range(0, 101 - x):</p><h1 id="计算鸡雏的数量" tabindex="-1">计算鸡雏的数量 <a class="header-anchor" href="#计算鸡雏的数量" aria-label="Permalink to &quot;计算鸡雏的数量&quot;">​</a></h1><p>z = 100 - x - y</p><h1 id="检查是否满足花费100元的条件" tabindex="-1">检查是否满足花费100元的条件 <a class="header-anchor" href="#检查是否满足花费100元的条件" aria-label="Permalink to &quot;检查是否满足花费100元的条件&quot;">​</a></h1><p>if 5<em>x + 3</em>y + z/3 == 100: print(x, y, z)</p><p>这段代码通过双层循环遍历鸡翁和鸡母的可能数量，并计算出鸡雏的数量。然后，它检查这种组合是否能够满足总数为100只鸡、总价为100元的条件。如果条件满足，就打印出这种组合的鸡翁、鸡母和鸡雏的数量。这种枚举方法虽然简单，但能有效地解决问题。</p><p>方法二 利用了两个等式：a + b + c = 100 和 5a + 3b + c/3 = 100。通过数学推导</p><p>我们发现</p><h1 id="无需持续输入-直接执行一次" tabindex="-1">无需持续输入，直接执行一次 <a class="header-anchor" href="#无需持续输入-直接执行一次" aria-label="Permalink to &quot;无需持续输入，直接执行一次&quot;">​</a></h1><p>try: for i in range(4): # 公鸡数量是4的倍数，且因为要保证b为正，a的取值范围为0到3，即最多12只公鸡 a = 4 * i # 公鸡数量 b = 25 - 7 * i # 母鸡数量 c = 100 - a - b # 小鸡数量</p><h1 id="输出购买方案" tabindex="-1">输出购买方案 <a class="header-anchor" href="#输出购买方案" aria-label="Permalink to &quot;输出购买方案&quot;">​</a></h1><p>print(a, b, c) except: pass</p></div>',1)])])}const _=a(i,[["render",n]]);export{u as __pageData,_ as default};
